import{_ as r,o as t,c as a,a0 as o}from"./chunks/framework.ysVzM4be.js";const u=JSON.parse('{"title":"The homepage hero is a real herdr capture","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0028-the-homepage-hero-is-a-real-herdr-capture.md","filePath":"adr/0028-the-homepage-hero-is-a-real-herdr-capture.md"}'),s={name:"adr/0028-the-homepage-hero-is-a-real-herdr-capture.md"};function i(h,e,n,d,c,l){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="the-homepage-hero-is-a-real-herdr-capture" tabindex="-1">The homepage hero is a real herdr capture <a class="header-anchor" href="#the-homepage-hero-is-a-real-herdr-capture" aria-label="Permalink to &quot;The homepage hero is a real herdr capture&quot;">​</a></h1><p>Status: accepted.</p><p>The documentation homepage shows one hero image of the control plane at work. The six operation screenshots already render the control plane in a plain terminal from a deterministic PTY fixture, and a drift test guards them. The homepage should show the control plane in its real container, a herdr workspace, so a first visitor sees the product the way an operator runs it.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The hero is generated by a script, <code>npm run hero</code>. The script drives a real, isolated herdr: a fresh server in a temporary directory with its own socket, home, and config. It never touches the operator&#39;s live herdr session. The script makes one workspace, splits it into two panes, and runs the control plane in the left pane over the same deterministic fixture the operation screenshots use. A stub agent session runs in the right pane. An attached herdr client renders the workspace, and the script captures the client&#39;s screen with the shared ANSI renderer into <code>docs/public/hero.png</code>.</p><p>The hero is refreshed by hand. It is not in the drift test.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li>Draw a mock herdr chrome around the fixture. This was rejected: a mock drifts from the real herdr, and it costs a second renderer to keep.</li><li>Put the hero in the drift test. This was rejected: herdr owns the chrome (the sidebar, the pane borders, the tab bar), and the chrome changes when herdr changes. A drift test would fail on every herdr upgrade for a reason outside this project.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The control plane pane in the hero is deterministic: it comes from the same fixture as the operation screenshots, and its <code>gh</code> and <code>herdr</code> lookups resolve to the fixture&#39;s stubs. Only the herdr chrome varies, and it varies with herdr.</li><li>The hero is a manual artifact. Refresh it when herdr changes or when the main view changes in a way the homepage should reflect.</li><li>The capture is isolated. A failed or interrupted run leaves no herdr state outside the temporary directory, and the operator&#39;s session is never read or written.</li><li>The image lives in the site&#39;s static asset directory, <code>docs/public/</code>, and the homepage references it by site path.</li></ul>',10)])])}const m=r(s,[["render",i]]);export{u as __pageData,m as default};
